// Получаем все элементы из предыдущей ноды (HTTP Request к /points)
const items = $input.all();

// Берём chat_id из Telegram Trigger
const chat_id = $node["Telegram Trigger"].json["message"]["chat"]["id"];

// Ищем точку с соответствующим idTg
const matchedPoint = items.find(item => item.json["idTg"] == chat_id);

// Формируем текст сообщения
let text;
let found = false;
let pointName = null;
let pointId = null;

if (matchedPoint) {
    text = `Здравствуйте, ваша точка ${matchedPoint.json["name"]}`;
    found = true;
    pointName = matchedPoint.json["name"];
    pointId = matchedPoint.json["id"];
} else {
    text = `Не удалось найти привязанную точку к id: ${chat_id}`;
}

// Формируем payload для Telegram (с reply_markup)
const telegram_payload = {
    chat_id: chat_id,
    text: text,
    parse_mode: "HTML",
    reply_markup: {
        keyboard: [
            [
                {
                    text: "Создать заявку"
                }
            ]
        ],
        resize_keyboard: true
    }
};

// Возвращаем объект с данными и статусом
return { 
    data: telegram_payload,  // для отправки в Telegram
    found: found,            // true/false, нашли ли точку
    pointName: pointName,    // название точки (или null)
    pointId: pointId         // id точки (или null)
};

// Исходный массив заказанных товаров
const items = JSON.parse($('Получить данные для изменения').first().json.json);

// Получаем данные для сервера
const point_id = $('Получить данные для изменения').first().json.point_id || 0;
const point = $('Получить данные для изменения').first().json.point || "";
const tg_name = $('Telegram Trigger').first().json.callback_query.from.first_name;
const tg_username = $('Telegram Trigger').first().json.callback_query.from.username;
const text = $('Получить данные для изменения').first().json.message || "";

// Очищаем items от лишних полей, оставляем только то, что нужно серверу
const cleanedItems = items.map(item => ({
  product_id: item.product_id,
  product_type: item.product_type || "",
  product_subtype: item.product_subtype || "",
  product_name: item.product_name || "",
  product_count: item.product_count || 0,
  product_unit: item.product_unit || "",
  suppliers_id: item.suppliers_id,
  suppliers_name: item.suppliers_name || ""
}));

// Возвращаем только данные для сервера
return [
  {
    json: {
      point_id,
      tg_name,
      tg_username,
      point,
      items: cleanedItems
    }
  }
];

// Получаем данные из предыдущего шага
const responseData = $input.first().json.message.content;
const data = responseData.items;

// Проверяем, что структура корректная
if (!data || !Array.isArray(data)) {
  return [{ json: { error: "Некорректная структура данных: отсутствует массив items" } }];
}

// Получаем название точки (если передано)
const point = $('Get row(s)2').first().json.point || 'неизвестна';

// Максимальное количество товаров в одном предупреждении
const MAX_PRODUCTS_IN_WARNING = 3;

// Сопоставление типа товара => дни недели (0 = Воскресенье, 1 = Понедельник, ..., 6 = Суббота)
const typeDays = {
  "Упаковка": [5],                          // пт
  "Лимонады": [4],                          // чт
  "Продукты (часть товаров)": [1, 3, 5],    // пн, ср, пт
  "Пищеснаб": [1, 4],                       // пн, чт
  "Молочка": [1, 4],                        // пн, чт
  "Сосиски": [2, 4],                        // вт, чт
  "Вода": [1, 4],                           // пн, чт
  "Мука/Сахар": [1, 2, 3, 4],               // пн, вт, ср, чт
  "Ирексол софт сдоба": [1, 4],             // пн, чт
};

// Функция для проверки, является ли сегодня крайней пятницей месяца
function isLastFridayOfMonth() {
  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const lastDayOfMonth = new Date(currentYear, currentMonth + 1, 0);

  let lastFriday = new Date(lastDayOfMonth);
  while (lastFriday.getDay() !== 5) {
    lastFriday.setDate(lastFriday.getDate() - 1);
  }

  return today.getDate() === lastFriday.getDate() && 
         today.getMonth() === lastFriday.getMonth() && 
         today.getFullYear() === lastFriday.getFullYear();
}

// Получаем текущий день недели
const today = new Date().getDay();

// Группируем товары по типу
const typeGroups = {};
for (const item of data) {
  const type = item.product_type || "Прочее";
  if (!typeGroups[type]) {
    typeGroups[type] = [];
  }
  typeGroups[type].push(item.product_name || "Без названия");
}

// ============================================
// ФОРМИРУЕМ ТЕКСТ ЗАКАЗА
// ============================================

let output = `🛒 Ваш заказ (Точка ${point}):\n\n`;

// Если AI сгенерировал summary_text — используем его как есть
if (responseData.summary_text) {
  output += responseData.summary_text;
} else {
  // Fallback: если AI не вернул summary_text, формируем сами
  for (const item of data) {
    const name = item.product_name || "Без названия";
    const count = item.product_count || 0;
    output += `- ${name} — ${count}\n`;
  }

  // Добавляем статус заказа
  if (responseData.order_status === "needs_confirmation") {
    output += "\n⚠️ Проверьте заказ перед отправкой\n";
  } else if (responseData.order_status === "blocked") {
    output += "\n🚫 Заказ не может быть отправлен без уточнений\n";
  } else {
    output += "\nВсё верно? Нажмите «Подтвердить»";
  }
}

// ============================================
// ДОБАВЛЯЕМ ПРЕДУПРЕЖДЕНИЯ О ДНЯХ ЗАКАЗА
// ============================================

let dayWarnings = "";
const dayNames = ["Воскресенье", "Понедельник", "Вторник", "Среда", "Четверг", "Пятница", "Суббота"];

for (const [type, products] of Object.entries(typeGroups)) {
  const normalizedType = type.toLowerCase().trim();
  let shouldWarn = false;
  let message = "";

  // Особые случаи для "белизна" и "Вафел.полотно"
  if (normalizedType.includes("белизна") || normalizedType.includes("вафел")) {
    if (!isLastFridayOfMonth()) {
      shouldWarn = true;
      let productsList;
      if (products.length > MAX_PRODUCTS_IN_WARNING) {
        const displayProducts = products.slice(0, MAX_PRODUCTS_IN_WARNING).join(", ");
        const remaining = products.length - MAX_PRODUCTS_IN_WARNING;
        productsList = `${displayProducts} и ещё ${remaining}`;
      } else {
        productsList = products.join(", ");
      }
      message = `⚠️ "${productsList}" отправляется только в последнюю пятницу месяца`;
    }
  } 
  // Обычные типы
  else {
    const allowedDays = typeDays[type];
    if (allowedDays && !allowedDays.includes(today)) {
      shouldWarn = true;
      const allowedDayNames = allowedDays.map(d => dayNames[d]).join(", ");
      let productsList;
      if (products.length > MAX_PRODUCTS_IN_WARNING) {
        const displayProducts = products.slice(0, MAX_PRODUCTS_IN_WARNING).join(", ");
        const remaining = products.length - MAX_PRODUCTS_IN_WARNING;
        productsList = `${displayProducts} и ещё ${remaining}`;
      } else {
        productsList = products.join(", ");
      }
      message = `⚠️ "${productsList}" желательно заказывать в: ${allowedDayNames}`;
    }
  }

  if (shouldWarn) {
    dayWarnings += `${message}\n`;
  }
}

// Добавляем предупреждения о днях заказа (если есть)
if (dayWarnings) {
  output += `\n\n${dayWarnings.trim()}`;
}

// Возвращаем результат с текстом и данными
return [{ 
  json: { 
    text: output.trim(), 
    data,
    order_status: responseData.order_status || "ready"
  } 
}];

