// Получаем входные данные
const inputData = $('HTTP Request5').all();

// Множество для хранения уникальных единиц измерения
const uniqueUnits = new Set();

// Обрабатываем каждый элемент входных данных
inputData.forEach(item => {
  const data = item.json;

  // Проверяем, есть ли объект "Поставщики"
  if (data.Поставщики) {
    // Перебираем всех поставщиков
    Object.keys(data.Поставщики).forEach(supplierName => {
      const supplier = data.Поставщики[supplierName];

      // Проверяем, есть ли массив products
      if (supplier.products && Array.isArray(supplier.products)) {
        // Перебираем продукты и добавляем unit в Set
        supplier.products.forEach(product => {
          if (product.unit) {
            uniqueUnits.add(product.unit);
          }
        });
      }
    });
  }
});

// Возвращаем массив уникальных единиц измерения
return [{ json: { units: Array.from(uniqueUnits) } }];

// Получаем данные из входящего JSON
const orders = $input.all();

// Обрабатываем каждый заказ
const results = orders.map(order => {
  const data = order.json;

  // Название точки
  const pointName = data.point?.name || data.tg_name || 'Неизвестная точка';

  // Формируем список товаров
  const itemsList = data.items.map(item => {
    // Определяем правильную форму единицы измерения
    let unitText = item.unit;

    // Склонение единиц измерения в зависимости от количества
    if (item.unit === 'бут.') {
      if (item.count === 1) {
        unitText = 'бутылка';
      } else if (item.count >= 2 && item.count <= 4) {
        unitText = 'бутылки';
      } else {
        unitText = 'бутылок';
      }
    }

    return `- ${item.name} — ${item.count} ${unitText}`;
  }).join('\n');

  // Формируем итоговое сообщение
  const message = `Точка ${pointName} отправила заказ:\n\n${itemsList}`;

  return {
    json: {
      message: message,
      order_id: data.id,
      point_id: data.point_id,
      point_name: pointName
    }
  };
});

return results;

const tg = $('Telegram Trigger').first().json;

// Извлекаем Telegram ID из любого возможного источника
const telegramId =
  (tg.callback_query?.from?.id?.toString()) ||
  (tg.message?.from?.id?.toString()) ||
  null;

// Получаем все входные элементы (ваш массив организаций)
const organizations = $input.all().map(item => item.json);

// Ищем организацию, у которой idTg совпадает с telegramId
const found = organizations.find(org => org.idTg === telegramId);

// Формируем результат
return [{
  json: {
    name: found ? found.name : null,
    point_id: found ? found.id : null,  
    found: !!found,
    telegramId: telegramId
  }
}];
